import sys

def find_nth_element(n):
    if n == 1:
        return 1
    if n == 2:
        return 2
    if n == 3:
        return 3
    if n == 4:
        return 4

    # Calculate the position in the sequence
    k = (n - 5) // 4 + 1
    r = (n - 5) % 4

    # Determine the value based on the position
    if r == 0:
        return 4 * k + 3
    elif r == 1:
        return 4 * k + 1
    elif r == 2:
        return 4 * k + 2
    else:
        return 4 * k

